function is(path,volume,regex){
	dl=path+","+volume;
	d=java.getElements(dl).toArray();
	list=d.map((a,i)=>{
		name=a.select("a").text();
		link=a.select("a").attr("href")
		dt=a.select("dt").text();
		title=a.attr("title");
		name=String(name).replace(regex,"")
		j={
			text:name,
			href:link,
			volume:dt,
			info:title
			};
		return JSON.stringify(j)
		})
		return list
	}

function no(path,regex){
	a=java.getElements(path).toArray();
	list=a.map((a,i)=>{
		name=a.select("a").text();
		link=a.select("a").attr("href")
		title=a.attr("title");
		name=String(name).replace(regex,"")
		j={
			text:name,
			href:link,
			info:title
			};
		return JSON.stringify(j)
		})
		return list
	}

list;

